// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // Fuzzed params: target calldata and a flag telling the helper whether to revert or not
    function testFuzz_property(bytes memory data, bool shouldRevert) public {
        // deploy a helper that either reverts or records the calldata
        CalleeHelper helper = new CalleeHelper(shouldRevert);

        // Try calling c.forward to the helper. The property:
        // Reference: forward(callee, data) returns (does not revert) exactly when callee.call(data) succeeds.
        // We observe success vs failure via try/catch around c.forward.
        bool ok;
        try c.forward(address(helper), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // The helper recorded whether it observed a call (only when it does not revert).
        // If helper is non-reverting, it will have been called and recorded the calldata; then c.forward must have succeeded.
        // If helper is set to revert, then call should fail and c.forward should revert.
        // Therefore the invariant: ok == (!shouldRevert)
        assertTrue(ok == (!shouldRevert));
    }
}

// Helper that either reverts on any call, or records that it was called and the calldata
contract CalleeHelper {
    bool public shouldRevert;
    bool public called;
    bytes public lastData;

    constructor(bool _shouldRevert) {
        shouldRevert = _shouldRevert;
    }

    fallback() external payable {
        if (shouldRevert) revert("revert by helper");
        called = true;
        lastData = msg.data;
    }

    receive() external payable {
        if (shouldRevert) revert("revert by helper");
        called = true;
        lastData = "";
    }
}
